const e="CZdj694qgjU",t="CZdj694qgjU",o="Learn English FAST: Talk About Feelings Like a Native – Day 12 | Shadowing English Speaking Practice",a="Speak English Daily",i="A1",n="Chủ đề Cảm xúc",l=41,d=2022,s="manual",r=JSON.parse(`[{"start":0,"end":1.3,"text":"Hello everyone.","words":[["Hello everyone.",0]],"ipa":"/Hello everyone/"},{"start":1.3,"end":4.07,"text":"Welcome back to Speak English Daily.","words":[["Welcome back to Speak English Daily.",1.3]],"ipa":"/Welcome back to Speak English Daily/"},{"start":4.07,"end":16.7,"text":"I'm Emma Today today is day 12 of our 30-day English shadowing challenge One topic every day to transform your English speaking skills.","words":[["I'm Emma",4.07],["Today today is day 12 of our",5.1],["30-day English shadowing challenge",7.67],["One topic every day to transform your English speaking skills.",10.6]],"ipa":"/I'm Emma Today today is day 12 of our 30-day English shadowing challenge One topic every day to transform your English speaking skills/"},{"start":16.7,"end":22.63,"text":"Today we're diving deep into talking about feelings like a native speaker.","words":[["Today we're diving deep into talking about",16.7],["feelings like a native speaker.",19.67]],"ipa":"/Today we're diving deep into talking about feelings like a native speaker/"},{"start":22.7,"end":24.97,"text":"\\"I'm happy\\" - Really?","words":[["\\"I'm happy\\" - Really?",22.7]],"ipa":"/I'm happy\\" - Really/"},{"start":24.97,"end":32.3,"text":"That's ALL you can say when your heart is exploding with joy?","words":[["That's ALL you can say when your heart is exploding with joy?",24.97]],"ipa":"/That's ALL you can say when your heart is exploding with joy/"},{"start":32.3,"end":35.2,"text":"Think about this moment.","words":[["Think about this moment.",32.3]],"ipa":"/Think about this moment/"},{"start":35.2,"end":41,"text":"You're having coffee with a friend who suddenly looks worried.","words":[["You're having coffee with a friend who suddenly looks worried.",35.2]],"ipa":"/You're having coffee with a friend who suddenly looks worried/"},{"start":41,"end":51.17,"text":"They share something personal with you, but when they ask, \\"How do you feel about this?\\" your mind freezes.","words":[["They share something personal with you, but when they ask,",41],["\\"How do you feel about this?\\" your mind freezes.",46.17]],"ipa":"/They share something personal with you, but when they ask How do you feel about this?\\" your mind freezes/"},{"start":51.17,"end":67.37,"text":"You know exactly what you want to say in your native language, but in English, you can only manage \\"It's... good\\" or \\"I think... okay.\\"","words":[["You know exactly what you want to say in your native language,",51.17],["but in English, you can only manage",56.27],["\\"It's... good\\" or \\"I think... okay.\\"",60.3]],"ipa":"/You know exactly what you want to say in your native language but in English, you can only manage It's... good\\" or \\"I think... okay/"},{"start":67.37,"end":69.37,"text":"Here's another situation.","words":[["Here's another situation.",67.37]],"ipa":"/Here's another situation/"},{"start":69.63,"end":75.3,"text":"You're feeling really excited about about something amazing that happened to you.","words":[["You're feeling really excited about",69.63],["about something amazing that happened to you.",72.03]],"ipa":"/You're feeling really excited about about something amazing that happened to you/"},{"start":75.5,"end":85.8,"text":"You want to share this joy with your English-speaking friends, but you don't know how to express that bubbling happiness inside you.","words":[["You want to share this joy with your English-speaking friends,",75.5],["but you don't know how to express that",80],["bubbling happiness inside you.",83.27]],"ipa":"/You want to share this joy with your English-speaking friends but you don't know how to express that bubbling happiness inside you/"},{"start":85.8,"end":92.27,"text":"You end up just saying \\"I'm happy\\" when you want to say so much more.","words":[["You end up just saying \\"I'm happy\\"",85.8],["when you want to say so much more.",89.23]],"ipa":"/You end up just saying \\"I'm happy when you want to say so much more/"},{"start":92.27,"end":98.07,"text":"This happens to English learners everywhere, every single day.","words":[["This happens to English learners everywhere, every single day.",92.27]],"ipa":"/This happens to English learners everywhere, every single day/"},{"start":98.07,"end":107.23,"text":"The gap between what you feel and and what you can express creates distance in your relationships.","words":[["The gap between what you feel and",98.07],["and what you can express creates distance in your relationships.",101.1]],"ipa":"/The gap between what you feel and and what you can express creates distance in your relationships/"},{"start":107.23,"end":112.47,"text":"But today, we're closing that gap forever.","words":[["But today, we're closing that gap forever.",107.23]],"ipa":"/But today, we're closing that gap forever/"},{"start":112.67,"end":117.47,"text":"This is going to be transformational.","words":[["This is going to be transformational.",112.67]],"ipa":"/This is going to be transformational/"},{"start":117.7,"end":129.67,"text":"Day 12 is all about Emotional Connection Talking about feelings isn't just vocabulary - it's about building real relationships.","words":[["Day 12 is all about Emotional Connection",117.7],["Talking about feelings isn't just vocabulary",121.9],["- it's about building real relationships.",126.17]],"ipa":"/Day 12 is all about Emotional Connection Talking about feelings isn't just vocabulary it's about building real relationships/"},{"start":129.8,"end":138.27,"text":"It's about being understood and understanding others at a deeper level.","words":[["It's about being understood",129.8],["and understanding others at a deeper level.",132.5]],"ipa":"/It's about being understood and understanding others at a deeper level/"},{"start":138.47,"end":157,"text":"Today's complete lesson includes 60 essential phrases for every emotional situation, real-life conversations about feelings,, your personal feelings challenge to practice today.","words":[["Today's complete lesson includes 60 essential phrases",138.47],["for every emotional situation,",144],["real-life conversations about feelings,",147.2],[", your personal feelings challenge to practice today.",151.3]],"ipa":"/Today's complete lesson includes 60 essential phrases for every emotional situation real-life conversations about feelings your personal feelings challenge to practice today/"},{"start":157.1,"end":168.57,"text":"By the end of this lesson, You'll have the confidence to express your emotions naturally and connect with people's hearts in English.","words":[["By the end of this lesson,",157.1],["You'll have the confidence to express your emotions naturally",159.17],["and connect with people's hearts in English.",164.23]],"ipa":"/By the end of this lesson You'll have the confidence to express your emotions naturally and connect with people's hearts in English/"},{"start":168.57,"end":173.63,"text":"Are you ready to never feel stuck when talking about feelings?","words":[["Are you ready to never feel stuck when talking about feelings?",168.57]],"ipa":"/Are you ready to never feel stuck when talking about feelings/"},{"start":173.63,"end":180.33,"text":"Let's transform your emotional vocabulary right now.","words":[["Let's transform your emotional vocabulary right now.",173.63]],"ipa":"/Let's transform your emotional vocabulary right now/"},{"start":180.33,"end":191.2,"text":"60 Golden Sentences - shadowing practice 60 essential phrases sounds like a lot?","words":[["60 Golden Sentences - shadowing practice",180.33],["60 essential phrases sounds like a lot?",187.37]],"ipa":"/60 Golden Sentences - shadowing practice 60 essential phrases sounds like a lot/"},{"start":191.43,"end":196.93,"text":"Don't worry. Just save this video and come back anytime.","words":[["Don't worry. Just save this video and come back anytime.",191.43]],"ipa":"/Don't worry. Just save this video and come back anytime/"},{"start":197.03,"end":204.77,"text":"Use the chapters in the description to jump to any part you wanna practice.","words":[["Use the chapters in the description",197.03],["to jump to any part you wanna practice.",200.07]],"ipa":"/Use the chapters in the description to jump to any part you wanna practice/"},{"start":204.77,"end":210,"text":"Here are your 60 essential phrases for talking about feelings.","words":[["Here are your 60 essential phrases for talking about feelings.",204.77]],"ipa":"/Here are your 60 essential phrases for talking about feelings/"},{"start":210,"end":212.87,"text":"I'll say each one three times.","words":[["I'll say each one three times.",210]],"ipa":"/I'll say each one three times/"},{"start":213,"end":220.9,"text":"Normal speed first, then slow and clear then normal speed again.","words":[["Normal speed first, then slow and clear",213],["then normal speed again.",217.77]],"ipa":"/Normal speed first, then slow and clear then normal speed again/"},{"start":221.17,"end":234.77,"text":"And remember don't just repeat these phrases Shadow everything I say. Copy me completely Every word, every pause, every emotion.","words":[["And remember don't just repeat these phrases",221.17],["Shadow everything I say. Copy me completely",225.4],["Every word, every pause, every emotion.",230.17]],"ipa":"/And remember don't just repeat these phrases Shadow everything I say. Copy me completely Every word, every pause, every emotion/"},{"start":234.77,"end":241.83,"text":"Feel the rhythm. Train your mouth, your ears, and your brain all at once.","words":[["Feel the rhythm. Train your mouth,",234.77],["your ears, and your brain all at once.",237.9]],"ipa":"/Feel the rhythm. Train your mouth your ears, and your brain all at once/"},{"start":242,"end":246.73,"text":"Imagine you are me. You're not just learning English.","words":[["Imagine you are me. You're not just learning English.",242]],"ipa":"/Imagine you are me. You're not just learning English/"},{"start":246.73,"end":249.57,"text":"You're becoming English.","words":[["You're becoming English.",246.73]],"ipa":"/You're becoming English/"},{"start":249.57,"end":256.03,"text":"You're rewriting your brain to think, breathe, and speak like a native.","words":[["You're rewriting your brain to think, breathe, and speak like a native.",249.57]],"ipa":"/You're rewriting your brain to think, breathe, and speak like a native/"},{"start":256.03,"end":263.13,"text":"This is your transformation moment. Don't waste it.","words":[["This is your transformation moment. Don't waste it.",256.03]],"ipa":"/This is your transformation moment. Don't waste it/"},{"start":263.17,"end":266.07,"text":"Now you repeat after each one.","words":[["Now you repeat after each one.",263.17]],"ipa":"/Now you repeat after each one/"},{"start":266.07,"end":269.63,"text":"Ready? Let's go.","words":[["Ready? Let's go.",266.07]],"ipa":"/Ready? Let's go/"},{"start":269.73,"end":276.17,"text":"But wait - before we dive in, I want you to bookmark this exact moment.","words":[["But wait - before we dive in, I want you to bookmark this exact moment.",269.73]],"ipa":"/But wait - before we dive in, I want you to bookmark this exact moment/"},{"start":276.17,"end":288.77,"text":"By the time we finish these 60 phrases, you'll speak about emotions like you've lived in an English speaking country for years!","words":[["By the time we finish these 60 phrases,",276.17],["you'll speak about emotions",279.67],["like you've lived in an English speaking country for years!",281.57]],"ipa":"/By the time we finish these 60 phrases you'll speak about emotions like you've lived in an English speaking country for years/"},{"start":288.77,"end":302.63,"text":"Happy and Positive Feelings These are perfect for good days and positive moments.","words":[["Happy and Positive Feelings",288.77],["These are perfect for good days and positive moments.",295.87]],"ipa":"/Happy and Positive Feelings These are perfect for good days and positive moments/"},{"start":303.27,"end":316.6,"text":"1. I'm feeling great today.","words":[["1. I'm feeling great today.",303.27]],"ipa":"/1. I'm feeling great today/"},{"start":317.1,"end":327.5,"text":"2. I'm so happy right now.","words":[["2. I'm so happy right now.",317.1]],"ipa":"/2. I'm so happy right now/"},{"start":327.77,"end":338.67,"text":"3. I feel amazing.","words":[["3. I feel amazing.",327.77]],"ipa":"/3. I feel amazing/"},{"start":338.87,"end":350.83,"text":"4. I'm in a good mood.","words":[["4. I'm in a good mood.",338.87]],"ipa":"/4. I'm in a good mood/"},{"start":351.23,"end":363.57,"text":"5. I feel wonderful.","words":[["5. I feel wonderful.",351.23]],"ipa":"/5. I feel wonderful/"},{"start":363.87,"end":376.73,"text":"6. I'm excited about this.","words":[["6. I'm excited about this.",363.87]],"ipa":"/6. I'm excited about this/"},{"start":377,"end":388.57,"text":"7. I feel so lucky.","words":[["7. I feel so lucky.",377]],"ipa":"/7. I feel so lucky/"},{"start":388.9,"end":399.93,"text":"8. This makes me happy.","words":[["8. This makes me happy.",388.9]],"ipa":"/8. This makes me happy/"},{"start":400.43,"end":411.93,"text":"9. I'm feeling positive.","words":[["9. I'm feeling positive.",400.43]],"ipa":"/9. I'm feeling positive/"},{"start":412.57,"end":423.13,"text":"10. I feel grateful.","words":[["10. I feel grateful.",412.57]],"ipa":"/10. I feel grateful/"},{"start":423.6,"end":435.13,"text":"Sad and Difficult Feelings Use these when life feels hard or challenging.","words":[["Sad and Difficult Feelings",423.6],["Use these when life feels hard or challenging.",429.17]],"ipa":"/Sad and Difficult Feelings Use these when life feels hard or challenging/"},{"start":435.5,"end":447.8,"text":"11. I'm feeling sad today.","words":[["11. I'm feeling sad today.",435.5]],"ipa":"/11. I'm feeling sad today/"},{"start":448.3,"end":459.53,"text":"12. I feel a bit down.","words":[["12. I feel a bit down.",448.3]],"ipa":"/12. I feel a bit down/"},{"start":459.83,"end":471.53,"text":"13. I'm not feeling well.","words":[["13. I'm not feeling well.",459.83]],"ipa":"/13. I'm not feeling well/"},{"start":471.9,"end":482,"text":"14. I feel disappointed.","words":[["14. I feel disappointed.",471.9]],"ipa":"/14. I feel disappointed/"},{"start":482.37,"end":495,"text":"15. I'm feeling lonely.","words":[["15. I'm feeling lonely.",482.37]],"ipa":"/15. I'm feeling lonely/"},{"start":495.2,"end":506.1,"text":"16. This makes me sad.","words":[["16. This makes me sad.",495.2]],"ipa":"/16. This makes me sad/"},{"start":506.67,"end":515.5,"text":"17. I feel hurt.","words":[["17. I feel hurt.",506.67]],"ipa":"/17. I feel hurt/"},{"start":515.97,"end":527.67,"text":"18. I'm having a bad day.","words":[["18. I'm having a bad day.",515.97]],"ipa":"/18. I'm having a bad day/"},{"start":527.97,"end":540.33,"text":"19. I feel upset.","words":[["19. I feel upset.",527.97]],"ipa":"/19. I feel upset/"},{"start":540.8,"end":552.23,"text":"20. I'm feeling blue.","words":[["20. I'm feeling blue.",540.8]],"ipa":"/20. I'm feeling blue/"},{"start":552.57,"end":559.6,"text":"Excellent! now let's learn about worried and anxious feelings.","words":[["Excellent! now let's learn about worried and anxious feelings.",552.57]],"ipa":"/Excellent! now let's learn about worried and anxious feelings/"},{"start":559.87,"end":571.57,"text":"Worried and Anxious Feelings Perfect for when you're feeling nervous or stressed.","words":[["Worried and Anxious Feelings",559.87],["Perfect for when you're feeling nervous or stressed.",565.67]],"ipa":"/Worried and Anxious Feelings Perfect for when you're feeling nervous or stressed/"},{"start":571.8,"end":582.67,"text":"21. I'm feeling worried.","words":[["21. I'm feeling worried.",571.8]],"ipa":"/21. I'm feeling worried/"},{"start":583,"end":593.33,"text":"22. I feel nervous.","words":[["22. I feel nervous.",583]],"ipa":"/22. I feel nervous/"},{"start":593.67,"end":604.4,"text":"23. I'm feeling anxious.","words":[["23. I'm feeling anxious.",593.67]],"ipa":"/23. I'm feeling anxious/"},{"start":604.67,"end":615.47,"text":"24. I feel stressed.","words":[["24. I feel stressed.",604.67]],"ipa":"/24. I feel stressed/"},{"start":615.8,"end":625.23,"text":"25. I'm feeling scared.","words":[["25. I'm feeling scared.",615.8]],"ipa":"/25. I'm feeling scared/"},{"start":625.5,"end":636.87,"text":"26. I feel uncertain.","words":[["26. I feel uncertain.",625.5]],"ipa":"/26. I feel uncertain/"},{"start":637.17,"end":647.5,"text":"27. I'm feeling overwhelmed.","words":[["27. I'm feeling overwhelmed.",637.17]],"ipa":"/27. I'm feeling overwhelmed/"},{"start":647.87,"end":660.37,"text":"28. This makes me nervous.","words":[["28. This makes me nervous.",647.87]],"ipa":"/28. This makes me nervous/"},{"start":660.6,"end":669.73,"text":"29. I feel tense.","words":[["29. I feel tense.",660.6]],"ipa":"/29. I feel tense/"},{"start":670,"end":680.53,"text":"30. I'm feeling uneasy.","words":[["30. I'm feeling uneasy.",670]],"ipa":"/30. I'm feeling uneasy/"},{"start":680.87,"end":687.77,"text":"Great job! Next let's talk about angry and frustrated feelings.","words":[["Great job! Next let's talk about angry and frustrated feelings.",680.87]],"ipa":"/Great job! Next let's talk about angry and frustrated feelings/"},{"start":687.83,"end":701.5,"text":"Angry and Frustrated Feelings Use these when you're feeling frustrated or angry.","words":[["Angry and Frustrated Feelings",687.83],["Use these when you're feeling frustrated or angry.",694.7]],"ipa":"/Angry and Frustrated Feelings Use these when you're feeling frustrated or angry/"},{"start":701.8,"end":712.2,"text":"31. I'm feeling angry.","words":[["31. I'm feeling angry.",701.8]],"ipa":"/31. I'm feeling angry/"},{"start":712.5,"end":723.23,"text":"32. I feel frustrated.","words":[["32. I feel frustrated.",712.5]],"ipa":"/32. I feel frustrated/"},{"start":723.63,"end":734.33,"text":"33. I'm feeling annoyed.","words":[["33. I'm feeling annoyed.",723.63]],"ipa":"/33. I'm feeling annoyed/"},{"start":734.63,"end":744.73,"text":"34. This makes me mad.","words":[["34. This makes me mad.",734.63]],"ipa":"/34. This makes me mad/"},{"start":745.03,"end":753.93,"text":"35. I feel irritated.","words":[["35. I feel irritated.",745.03]],"ipa":"/35. I feel irritated/"},{"start":754.3,"end":763.97,"text":"36. I'm feeling upset.","words":[["36. I'm feeling upset.",754.3]],"ipa":"/36. I'm feeling upset/"},{"start":764.23,"end":772.93,"text":"37. I feel bothered.","words":[["37. I feel bothered.",764.23]],"ipa":"/37. I feel bothered/"},{"start":773.23,"end":783.63,"text":"38. I'm not happy about this.","words":[["38. I'm not happy about this.",773.23]],"ipa":"/38. I'm not happy about this/"},{"start":784.03,"end":802.67,"text":"Wonderful! Now let's learn about tired and energy feelings Tired and Energy Feelings Great for describing your energy levels.","words":[["Wonderful! Now let's learn about tired and energy feelings",784.03],["Tired and Energy Feelings",791.17],["Great for describing your energy levels.",797.03]],"ipa":"/Wonderful! Now let's learn about tired and energy feelings Tired and Energy Feelings Great for describing your energy levels/"},{"start":803.1,"end":813.07,"text":"39. I'm feeling tired.","words":[["39. I'm feeling tired.",803.1]],"ipa":"/39. I'm feeling tired/"},{"start":813.47,"end":823.87,"text":"40. I feel exhausted.","words":[["40. I feel exhausted.",813.47]],"ipa":"/40. I feel exhausted/"},{"start":824.43,"end":835.17,"text":"41. I'm feeling sleepy.","words":[["41. I'm feeling sleepy.",824.43]],"ipa":"/41. I'm feeling sleepy/"},{"start":835.5,"end":845.6,"text":"42. I feel drained.","words":[["42. I feel drained.",835.5]],"ipa":"/42. I feel drained/"},{"start":845.93,"end":856.07,"text":"43. I'm feeling energetic.","words":[["43. I'm feeling energetic.",845.93]],"ipa":"/43. I'm feeling energetic/"},{"start":856.37,"end":866.27,"text":"44. I feel refreshed.","words":[["44. I feel refreshed.",856.37]],"ipa":"/44. I feel refreshed/"},{"start":866.57,"end":876.97,"text":"45. I'm feeling lazy.","words":[["45. I'm feeling lazy.",866.57]],"ipa":"/45. I'm feeling lazy/"},{"start":877.27,"end":886.7,"text":"46. I feel worn out.","words":[["46. I feel worn out.",877.27]],"ipa":"/46. I feel worn out/"},{"start":887,"end":893.17,"text":"Amazing! Now, let’s move on to asking about feelings.","words":[["Amazing! Now, let’s move on to asking about feelings.",887]],"ipa":"/Amazing! Now, let’s move on to asking about feelings/"},{"start":893.77,"end":907.4,"text":"Asking About Feelings Natural ways to ask how someone feels.","words":[["Asking About Feelings",893.77],["Natural ways to ask how someone feels.",900]],"ipa":"/Asking About Feelings Natural ways to ask how someone feels/"},{"start":907.4,"end":920.03,"text":"47. How are you feeling?","words":[["47. How are you feeling?",907.4]],"ipa":"/47. How are you feeling/"},{"start":920.03,"end":929.23,"text":"48. What's wrong?","words":[["48. What's wrong?",920.03]],"ipa":"/48. What's wrong/"},{"start":929.23,"end":940.23,"text":"49. Are you okay?","words":[["49. Are you okay?",929.23]],"ipa":"/49. Are you okay/"},{"start":940.23,"end":953.9,"text":"50. How do you feel about this?","words":[["50. How do you feel about this?",940.23]],"ipa":"/50. How do you feel about this/"},{"start":953.9,"end":963.53,"text":"51. What's the matter?","words":[["51. What's the matter?",953.9]],"ipa":"/51. What's the matter/"},{"start":963.53,"end":974.57,"text":"52. Is everything alright?","words":[["52. Is everything alright?",963.53]],"ipa":"/52. Is everything alright/"},{"start":974.57,"end":984.2,"text":"53. You seem upset.","words":[["53. You seem upset.",974.57]],"ipa":"/53. You seem upset/"},{"start":984.2,"end":994.8,"text":"54. Are you feeling better?","words":[["54. Are you feeling better?",984.2]],"ipa":"/54. Are you feeling better/"},{"start":994.8,"end":1005.33,"text":"55. What's bothering you?","words":[["55. What's bothering you?",994.8]],"ipa":"/55. What's bothering you/"},{"start":1005.33,"end":1015.3,"text":"56. How was your day?","words":[["56. How was your day?",1005.33]],"ipa":"/56. How was your day/"},{"start":1015.33,"end":1029.43,"text":"Responding to Feelings Perfect responses when someone shares their feelings.","words":[["Responding to Feelings",1015.33],["Perfect responses when someone shares their feelings.",1021.17]],"ipa":"/Responding to Feelings Perfect responses when someone shares their feelings/"},{"start":1029.77,"end":1043.8,"text":"57. I understand how you feel.","words":[["57. I understand how you feel.",1029.77]],"ipa":"/57. I understand how you feel/"},{"start":1044.27,"end":1055.33,"text":"58. I'm sorry you feel that way.","words":[["58. I'm sorry you feel that way.",1044.27]],"ipa":"/58. I'm sorry you feel that way/"},{"start":1055.33,"end":1067.37,"text":"59. That sounds difficult.","words":[["59. That sounds difficult.",1055.33]],"ipa":"/59. That sounds difficult/"},{"start":1067.77,"end":1077.77,"text":"60. I'm here for you.","words":[["60. I'm here for you.",1067.77]],"ipa":"/60. I'm here for you/"},{"start":1078.1,"end":1088.23,"text":"Fantastic! You did it. You've mastered 60 essential phrases for talking about feelings.","words":[["Fantastic! You did it. You've mastered 60 essential phrases",1078.1],["for talking about feelings.",1084.3]],"ipa":"/Fantastic! You did it. You've mastered 60 essential phrases for talking about feelings/"},{"start":1088.23,"end":1093.53,"text":"Now, let's use these phrases in real situation.","words":[["Now, let's use these phrases in real situation.",1088.23]],"ipa":"/Now, let's use these phrases in real situation/"},{"start":1093.53,"end":1097.4,"text":"We have three beautiful scenarios for you today.","words":[["We have three beautiful scenarios for you today.",1093.53]],"ipa":"/We have three beautiful scenarios for you today/"},{"start":1097.4,"end":1102.67,"text":"🎯 PRO TIP: Don't just listen - LIVE these conversations.","words":[["🎯 PRO TIP: Don't just listen - LIVE these conversations.",1097.4]],"ipa":"/PRO TIP: Don't just listen - LIVE these conversations/"},{"start":1102.67,"end":1107.4,"text":"Feel the emotions. Imagine you're really there.","words":[["Feel the emotions. Imagine you're really there.",1102.67]],"ipa":"/Feel the emotions. Imagine you're really there/"},{"start":1107.4,"end":1112.43,"text":"This is how your brain remembers naturally.","words":[["This is how your brain remembers naturally.",1107.4]],"ipa":"/This is how your brain remembers naturally/"},{"start":1112.43,"end":1119.17,"text":"Scenario 1: I have Mark joining us to help with our dialogue practice.","words":[["Scenario 1: I have Mark joining us to help with our dialogue practice.",1112.43]],"ipa":"/Scenario 1: I have Mark joining us to help with our dialogue practice/"},{"start":1119.17,"end":1125.13,"text":"Mark will be our conversation partner for the first scenario.","words":[["Mark will be our conversation partner for the first scenario.",1119.17]],"ipa":"/Mark will be our conversation partner for the first scenario/"},{"start":1125.13,"end":1127.6,"text":"Shadow along with us.","words":[["Shadow along with us.",1125.13]],"ipa":"/Shadow along with us/"},{"start":1127.6,"end":1132.97,"text":"Speak both sides of the conversation out loud.","words":[["Speak both sides of the conversation out loud.",1127.6]],"ipa":"/Speak both sides of the conversation out loud/"},{"start":1132.97,"end":1139.13,"text":"Scenario 2 and 3: Here's where the magic happens.","words":[["Scenario 2 and 3: Here's where the magic happens.",1132.97]],"ipa":"/Scenario 2 and 3: Here's where the magic happens/"},{"start":1139.13,"end":1145.4,"text":"You'll be talking directly with me, your conversation partner and friend.","words":[["You'll be talking directly with me,",1139.13],["your conversation partner and friend.",1142.2]],"ipa":"/You'll be talking directly with me your conversation partner and friend/"},{"start":1145.4,"end":1150.93,"text":"When I pause, that's your cue to respond.","words":[["When I pause, that's your cue to respond.",1145.4]],"ipa":"/When I pause, that's your cue to respond/"},{"start":1150.93,"end":1155.53,"text":"Don't just listen. Live the conversation with me.","words":[["Don't just listen. Live the conversation with me.",1150.93]],"ipa":"/Don't just listen. Live the conversation with me/"},{"start":1155.53,"end":1157.67,"text":"Feel the emotions.","words":[["Feel the emotions.",1155.53]],"ipa":"/Feel the emotions/"},{"start":1157.67,"end":1162.13,"text":"Connect with the story and let your heart be in it.","words":[["Connect with the story and let your heart be in it.",1157.67]],"ipa":"/Connect with the story and let your heart be in it/"},{"start":1162.13,"end":1169.53,"text":"This is how you'll remember these patterns naturally and speak with confidence.","words":[["This is how you'll remember these patterns",1162.13],["naturally and speak with confidence.",1165.07]],"ipa":"/This is how you'll remember these patterns naturally and speak with confidence/"},{"start":1169.53,"end":1178.23,"text":"Now, let's dive into these scenarios together and make them come alive.","words":[["Now, let's dive into these scenarios together and make them come alive.",1169.53]],"ipa":"/Now, let's dive into these scenarios together and make them come alive/"},{"start":1178.5,"end":1195.87,"text":"Scenario 1: Checking on a friend Emma, you seem a bit quiet today. Are you okay?","words":[["Scenario 1: Checking on a friend",1178.5],["Emma, you seem a bit quiet today. Are you okay?",1189.8]],"ipa":"/Scenario 1: Checking on a friend Emma, you seem a bit quiet today. Are you okay/"},{"start":1195.87,"end":1203.2,"text":"Actually, I'm feeling a bit down. I had a difficult day at work.","words":[["Actually, I'm feeling a bit down. I had a difficult day at work.",1195.87]],"ipa":"/Actually, I'm feeling a bit down. I had a difficult day at work/"},{"start":1203.2,"end":1208.1,"text":"I'm sorry to hear that. What happened?","words":[["I'm sorry to hear that. What happened?",1203.2]],"ipa":"/I'm sorry to hear that. What happened/"},{"start":1208.1,"end":1211.5,"text":"My boss wasn't happy with my presentation.","words":[["My boss wasn't happy with my presentation.",1208.1]],"ipa":"/My boss wasn't happy with my presentation/"},{"start":1211.5,"end":1215.83,"text":"I feel disappointed in myself.","words":[["I feel disappointed in myself.",1211.5]],"ipa":"/I feel disappointed in myself/"},{"start":1215.83,"end":1219.87,"text":"That sounds really hard. But you know what?","words":[["That sounds really hard. But you know what?",1215.83]],"ipa":"/That sounds really hard. But you know what/"},{"start":1219.87,"end":1224.47,"text":"You're usually great at presentations.","words":[["You're usually great at presentations.",1219.87]],"ipa":"/You're usually great at presentations/"},{"start":1224.47,"end":1231.1,"text":"Thank you for saying that. I'm feeling a bit better now.","words":[["Thank you for saying that. I'm feeling a bit better now.",1224.47]],"ipa":"/Thank you for saying that. I'm feeling a bit better now/"},{"start":1231.1,"end":1235.3,"text":"I'm here for you if you need to talk more.","words":[["I'm here for you if you need to talk more.",1231.1]],"ipa":"/I'm here for you if you need to talk more/"},{"start":1235.3,"end":1240.43,"text":"I appreciate that. You're such a good friend.","words":[["I appreciate that. You're such a good friend.",1235.3]],"ipa":"/I appreciate that. You're such a good friend/"},{"start":1240.43,"end":1244,"text":"How are you feeling now?","words":[["How are you feeling now?",1240.43]],"ipa":"/How are you feeling now/"},{"start":1244,"end":1249.7,"text":"Much better. Thank you for listening.","words":[["Much better. Thank you for listening.",1244]],"ipa":"/Much better. Thank you for listening/"},{"start":1249.7,"end":1256.43,"text":"I'm glad you're feeling better. That's what friends are for.","words":[["I'm glad you're feeling better. That's what friends are for.",1249.7]],"ipa":"/I'm glad you're feeling better. That's what friends are for/"},{"start":1256.43,"end":1263.43,"text":"Perfect! See how we went from checking on feeling to offering support and connection?","words":[["Perfect! See how we went from checking on feeling",1256.43],["to offering support and connection?",1260.17]],"ipa":"/Perfect! See how we went from checking on feeling to offering support and connection/"},{"start":1263.43,"end":1266.3,"text":"That's the power of feelings talk.","words":[["That's the power of feelings talk.",1263.43]],"ipa":"/That's the power of feelings talk/"},{"start":1266.3,"end":1272.4,"text":"It builds real relationships.","words":[["It builds real relationships.",1266.3]],"ipa":"/It builds real relationships/"},{"start":1272.4,"end":1286.7,"text":"Scenario 2: Sharing Good News In this scenario, you're my close friend who just received amazing news.","words":[["Scenario 2: Sharing Good News",1272.4],["In this scenario, you're my close friend who just received amazing news.",1280.8]],"ipa":"/Scenario 2: Sharing Good News In this scenario, you're my close friend who just received amazing news/"},{"start":1286.7,"end":1291.23,"text":"You're bursting with excitement and can't wait to share it with me.","words":[["You're bursting with excitement and can't wait to share it with me.",1286.7]],"ipa":"/You're bursting with excitement and can't wait to share it with me/"},{"start":1291.23,"end":1295.8,"text":"Ready? Here we go!","words":[["Ready? Here we go!",1291.23]],"ipa":"/Ready? Here we go/"},{"start":1295.8,"end":1299.27,"text":"You look absolutely radiant today!","words":[["You look absolutely radiant today!",1295.8]],"ipa":"/You look absolutely radiant today/"},{"start":1299.27,"end":1302.6,"text":"Something amazing happened, didn't it?","words":[["Something amazing happened, didn't it?",1299.27]],"ipa":"/Something amazing happened, didn't it/"},{"start":1302.6,"end":1307,"text":"What's got you glowing?","words":[["What's got you glowing?",1302.6]],"ipa":"/What's got you glowing/"},{"start":1307.3,"end":1315.2,"text":"I'm feeling so excited right now!","words":[["I'm feeling so excited right now!",1307.3]],"ipa":"/I'm feeling so excited right now/"},{"start":1315.2,"end":1324.97,"text":"I just got accepted into my dream university!","words":[["I just got accepted into my dream university!",1315.2]],"ipa":"/I just got accepted into my dream university/"},{"start":1325.07,"end":1333.7,"text":"I can't believe it's real! That's incredible!","words":[["I can't believe it's real!",1325.07],["That's incredible!",1331.87]],"ipa":"/I can't believe it's real That's incredible/"},{"start":1333.7,"end":1336.9,"text":"I can feel your excitement through the screen!","words":[["I can feel your excitement through the screen!",1333.7]],"ipa":"/I can feel your excitement through the screen/"},{"start":1337.1,"end":1342.5,"text":"Tell me - how are you feeling about this incredible news?","words":[["Tell me - how are you feeling about this incredible news?",1337.1]],"ipa":"/Tell me - how are you feeling about this incredible news/"},{"start":1342.8,"end":1347.23,"text":"I'm feeling amazing!","words":[["I'm feeling amazing!",1342.8]],"ipa":"/I'm feeling amazing/"},{"start":1347.3,"end":1363.17,"text":"I've been waiting for this moment for so long I feel like I'm dreaming this makes me so happy I can literally see you beaming with happiness right now!","words":[["I've been waiting for this moment for so long",1347.3],["I feel like I'm dreaming this makes me so happy",1354.37],["I can literally see you beaming with happiness right now!",1358.67]],"ipa":"/I've been waiting for this moment for so long I feel like I'm dreaming this makes me so happy I can literally see you beaming with happiness right now/"},{"start":1363.17,"end":1371.5,"text":"Your energy is contagious - this is absolutely wonderful news!","words":[["Your energy is contagious - this is absolutely wonderful news!",1363.17]],"ipa":"/Your energy is contagious - this is absolutely wonderful news/"},{"start":1371.5,"end":1375.43,"text":"I feel so grateful!","words":[["I feel so grateful!",1371.5]],"ipa":"/I feel so grateful/"},{"start":1375.43,"end":1381.43,"text":"Thank you for being excited with me.","words":[["Thank you for being excited with me.",1375.43]],"ipa":"/Thank you for being excited with me/"},{"start":1381.43,"end":1392.13,"text":"I'm still feeling overwhelmed but in the best way possible!","words":[["I'm still feeling overwhelmed but in the best way possible!",1381.43]],"ipa":"/I'm still feeling overwhelmed but in the best way possible/"},{"start":1392.13,"end":1395.97,"text":"I'm getting goosebumps just listening to you!","words":[["I'm getting goosebumps just listening to you!",1392.13]],"ipa":"/I'm getting goosebumps just listening to you/"},{"start":1395.97,"end":1399.9,"text":"You know what? You absolutely deserve this happiness.","words":[["You know what? You absolutely deserve this happiness.",1395.97]],"ipa":"/You know what? You absolutely deserve this happiness/"},{"start":1399.9,"end":1404.67,"text":"How long have you been waiting for this moment?","words":[["How long have you been waiting for this moment?",1399.9]],"ipa":"/How long have you been waiting for this moment/"},{"start":1405.03,"end":1411.13,"text":"I've been preparing for two years!","words":[["I've been preparing for two years!",1405.03]],"ipa":"/I've been preparing for two years/"},{"start":1411.13,"end":1423.43,"text":"I was feeling so nervous about the results, but now I feel wonderful.","words":[["I was feeling so nervous about the results, but now I feel wonderful.",1411.13]],"ipa":"/I was feeling so nervous about the results, but now I feel wonderful/"},{"start":1423.43,"end":1429.83,"text":"I'm so lucky!","words":[["I'm so lucky!",1423.43]],"ipa":"/I'm so lucky/"},{"start":1429.83,"end":1431.87,"text":"You know what makes me happiest?","words":[["You know what makes me happiest?",1429.83]],"ipa":"/You know what makes me happiest/"},{"start":1431.87,"end":1435.3,"text":"Seeing you so genuinely excited.","words":[["Seeing you so genuinely excited.",1431.87]],"ipa":"/Seeing you so genuinely excited/"},{"start":1435.3,"end":1441.63,"text":"Thank you for letting me share this beautiful moment with you.","words":[["Thank you for letting me share this beautiful moment with you.",1435.3]],"ipa":"/Thank you for letting me share this beautiful moment with you/"},{"start":1441.63,"end":1449.77,"text":"I'm feeling so positive about everything now!","words":[["I'm feeling so positive about everything now!",1441.63]],"ipa":"/I'm feeling so positive about everything now/"},{"start":1449.77,"end":1457.5,"text":"Thank you for listening to me.","words":[["Thank you for listening to me.",1449.77]],"ipa":"/Thank you for listening to me/"},{"start":1457.5,"end":1464.13,"text":"This makes me feel even better!","words":[["This makes me feel even better!",1457.5]],"ipa":"/This makes me feel even better/"},{"start":1464.13,"end":1470.63,"text":"Excellent! Sharing positive feelings is just as important as supporting difficult ones.","words":[["Excellent! Sharing positive feelings is just",1464.13],["as important as supporting difficult ones.",1467.73]],"ipa":"/Excellent! Sharing positive feelings is just as important as supporting difficult ones/"},{"start":1470.63,"end":1477.07,"text":"You're building those emotional connections beautifully.","words":[["You're building those emotional connections beautifully.",1470.63]],"ipa":"/You're building those emotional connections beautifully/"},{"start":1477.33,"end":1485.63,"text":"Now, let's experience a very common situation - dealing with stress and overwhelm.","words":[["Now, let's experience a very common situation",1477.33],["- dealing with stress and overwhelm.",1481.97]],"ipa":"/Now, let's experience a very common situation dealing with stress and overwhelm/"},{"start":1486.23,"end":1501.13,"text":"Scenario 3: Dealing with Stress In this scenario, you're my caring friend who wants to help me feel better.","words":[["Scenario 3: Dealing with Stress",1486.23],["In this scenario, you're my caring friend",1494.9],["who wants to help me feel better.",1498.2]],"ipa":"/Scenario 3: Dealing with Stress In this scenario, you're my caring friend who wants to help me feel better/"},{"start":1501.13,"end":1504.13,"text":"You'll listen to my problems and offer support.","words":[["You'll listen to my problems and offer support.",1501.13]],"ipa":"/You'll listen to my problems and offer support/"},{"start":1504.13,"end":1508.87,"text":"Show me you care and help me feel less stressed.","words":[["Show me you care and help me feel less stressed.",1504.13]],"ipa":"/Show me you care and help me feel less stressed/"},{"start":1508.87,"end":1514.13,"text":"Ready? Here we go!","words":[["Ready? Here we go!",1508.87]],"ipa":"/Ready? Here we go/"},{"start":1514.13,"end":1519.53,"text":"I'm feeling completely overwhelmed about my exam tomorrow.","words":[["I'm feeling completely overwhelmed about my exam tomorrow.",1514.13]],"ipa":"/I'm feeling completely overwhelmed about my exam tomorrow/"},{"start":1519.53,"end":1524.97,"text":"My mind is racing and I can't seem to calm down.","words":[["My mind is racing and I can't seem to calm down.",1519.53]],"ipa":"/My mind is racing and I can't seem to calm down/"},{"start":1524.97,"end":1529.33,"text":"I understand how you feel.","words":[["I understand how you feel.",1524.97]],"ipa":"/I understand how you feel/"},{"start":1529.33,"end":1536.9,"text":"I feel the same way before big exams.","words":[["I feel the same way before big exams.",1529.33]],"ipa":"/I feel the same way before big exams/"},{"start":1536.9,"end":1542,"text":"Are you feeling very nervous?","words":[["Are you feeling very nervous?",1536.9]],"ipa":"/Are you feeling very nervous/"},{"start":1542,"end":1547.3,"text":"I feel so anxious that my hands are actually shaking.","words":[["I feel so anxious that my hands are actually shaking.",1542]],"ipa":"/I feel so anxious that my hands are actually shaking/"},{"start":1547.3,"end":1556.77,"text":"I've been studying for weeks, but I'm terrified I'll blank out and forget everything I learned.","words":[["I've been studying for weeks,",1547.3],["but I'm terrified I'll blank out and forget everything I learned.",1549.93]],"ipa":"/I've been studying for weeks but I'm terrified I'll blank out and forget everything I learned/"},{"start":1556.77,"end":1569.07,"text":"That sounds really difficult. I'm sorry you feel that way.","words":[["That sounds really difficult. I'm sorry you feel that way.",1556.77]],"ipa":"/That sounds really difficult. I'm sorry you feel that way/"},{"start":1569.07,"end":1586.2,"text":"Maybe try to take deep breaths? You're usually so smart!","words":[["Maybe try to take deep breaths? You're usually so smart!",1569.07]],"ipa":"/Maybe try to take deep breaths? You're usually so smart/"},{"start":1586.2,"end":1589.93,"text":"Your words mean so much to me right now.","words":[["Your words mean so much to me right now.",1586.2]],"ipa":"/Your words mean so much to me right now/"},{"start":1589.93,"end":1599.2,"text":"I'm feeling like the weight of the world is on my shoulders with this exam and everything else happening.","words":[["I'm feeling like the weight of the world is on my shoulders",1589.93],["with this exam and everything else happening.",1593.63]],"ipa":"/I'm feeling like the weight of the world is on my shoulders with this exam and everything else happening/"},{"start":1599.2,"end":1604.3,"text":"What else is bothering you?","words":[["What else is bothering you?",1599.2]],"ipa":"/What else is bothering you/"},{"start":1604.3,"end":1612.43,"text":"I'm here for you if you want to talk about it.","words":[["I'm here for you if you want to talk about it.",1604.3]],"ipa":"/I'm here for you if you want to talk about it/"},{"start":1612.43,"end":1617.6,"text":"You seem really upset.","words":[["You seem really upset.",1612.43]],"ipa":"/You seem really upset/"},{"start":1617.6,"end":1619.7,"text":"You're absolutely right.","words":[["You're absolutely right.",1617.6]],"ipa":"/You're absolutely right/"},{"start":1619.7,"end":1622.97,"text":"I can feel my breathing slowing down already.","words":[["I can feel my breathing slowing down already.",1619.7]],"ipa":"/I can feel my breathing slowing down already/"},{"start":1622.97,"end":1631.17,"text":"Sometimes we just need someone to remind us to pause and breathe.","words":[["Sometimes we just need someone to remind us to pause and breathe.",1622.97]],"ipa":"/Sometimes we just need someone to remind us to pause and breathe/"},{"start":1631.33,"end":1642.17,"text":"I'm feeling happy that you're feeling better!","words":[["I'm feeling happy that you're feeling better!",1631.33]],"ipa":"/I'm feeling happy that you're feeling better/"},{"start":1642.17,"end":1651.13,"text":"You're going to do great on your exam.","words":[["You're going to do great on your exam.",1642.17]],"ipa":"/You're going to do great on your exam/"},{"start":1651.4,"end":1659.8,"text":"I feel confident about that!","words":[["I feel confident about that!",1651.4]],"ipa":"/I feel confident about that/"},{"start":1659.8,"end":1663.4,"text":"I feel like a completely different person now.","words":[["I feel like a completely different person now.",1659.8]],"ipa":"/I feel like a completely different person now/"},{"start":1663.4,"end":1671.8,"text":"Thank you for being exactly what I needed - a caring friend who helped me find my calm again.","words":[["Thank you for being exactly what I needed",1663.4],["- a caring friend who helped me find my calm again.",1666.53]],"ipa":"/Thank you for being exactly what I needed a caring friend who helped me find my calm again/"},{"start":1671.8,"end":1680.37,"text":"I'm so glad you're feeling better now!","words":[["I'm so glad you're feeling better now!",1671.8]],"ipa":"/I'm so glad you're feeling better now/"},{"start":1680.37,"end":1685.67,"text":"That's what friends are for.","words":[["That's what friends are for.",1680.37]],"ipa":"/That's what friends are for/"},{"start":1685.67,"end":1698.6,"text":"Are you feeling more positive about tomorrow?","words":[["Are you feeling more positive about tomorrow?",1685.67]],"ipa":"/Are you feeling more positive about tomorrow/"},{"start":1698.6,"end":1707.13,"text":"Perfect! You've mastered feelings conversations in happy, sad, and stressful situations.","words":[["Perfect! You've mastered feelings conversations",1698.6],["in happy, sad, and stressful situations.",1703.07]],"ipa":"/Perfect! You've mastered feelings conversations in happy, sad, and stressful situations/"},{"start":1707.13,"end":1713.83,"text":"Now, it's time for your personalized feelings challenge.","words":[["Now, it's time for your personalized feelings challenge.",1707.13]],"ipa":"/Now, it's time for your personalized feelings challenge/"},{"start":1713.83,"end":1721.3,"text":"But first, let me give you the feelings talk confidence formula.","words":[["But first, let me give you the feelings talk confidence formula.",1713.83]],"ipa":"/But first, let me give you the feelings talk confidence formula/"},{"start":1721.3,"end":1725.33,"text":"Step 1: Check in with yourself.","words":[["Step 1: Check in with yourself.",1721.3]],"ipa":"/Step 1: Check in with yourself/"},{"start":1725.33,"end":1732.3,"text":"How are you feeling right now? Happy, tired, excited, worried?","words":[["How are you feeling right now? Happy, tired, excited, worried?",1725.33]],"ipa":"/How are you feeling right now? Happy, tired, excited, worried/"},{"start":1732.3,"end":1737.4,"text":"Be honest with yourself.","words":[["Be honest with yourself.",1732.3]],"ipa":"/Be honest with yourself/"},{"start":1737.4,"end":1741.37,"text":"Step 2: Choose your words.","words":[["Step 2: Choose your words.",1737.4]],"ipa":"/Step 2: Choose your words/"},{"start":1741.37,"end":1746.67,"text":"Pick three phrases from today's lesson that describe how you feel.","words":[["Pick three phrases from today's lesson that describe how you feel.",1741.37]],"ipa":"/Pick three phrases from today's lesson that describe how you feel/"},{"start":1746.67,"end":1757.87,"text":"For example: \\"I'm feeling good today,\\" \\"I feel grateful,\\" \\"I'm excited about this.\\"","words":[["For example: \\"I'm feeling good today,\\"",1746.67],["\\"I feel grateful,\\" \\"I'm excited about this.\\"",1750.37]],"ipa":"/For example: \\"I'm feeling good today I feel grateful,\\" \\"I'm excited about this/"},{"start":1757.87,"end":1761.67,"text":"Step 3: Practice out loud.","words":[["Step 3: Practice out loud.",1757.87]],"ipa":"/Step 3: Practice out loud/"},{"start":1761.97,"end":1769.2,"text":"Say your three phrases clearly. Feel the emotion as you speak.","words":[["Say your three phrases clearly. Feel the emotion as you speak.",1761.97]],"ipa":"/Say your three phrases clearly. Feel the emotion as you speak/"},{"start":1769.2,"end":1773.97,"text":"Step 4: Share with someone today.","words":[["Step 4: Share with someone today.",1769.2]],"ipa":"/Step 4: Share with someone today/"},{"start":1774.07,"end":1789.1,"text":"Use one phrase with a real person. It could be a friend, family member, colleague, or even someone you meet casually.","words":[["Use one phrase with a real person. It could be a friend,",1774.07],["family member, colleague, or even someone you meet casually.",1780.2]],"ipa":"/Use one phrase with a real person. It could be a friend family member, colleague, or even someone you meet casually/"},{"start":1789.1,"end":1792.73,"text":"Step 5: Ask someone else.","words":[["Step 5: Ask someone else.",1789.1]],"ipa":"/Step 5: Ask someone else/"},{"start":1792.73,"end":1797.23,"text":"Use one of our question phrases: \\"How are you feeling?\\"","words":[["Use one of our question phrases: \\"How are you feeling?\\"",1792.73]],"ipa":"/Use one of our question phrases: \\"How are you feeling/"},{"start":1797.23,"end":1805.3,"text":"or \\"Are you okay?\\" Show genuine interest in their answer.","words":[["or \\"Are you okay?\\" Show genuine interest in their answer.",1797.23]],"ipa":"/or \\"Are you okay?\\" Show genuine interest in their answer/"},{"start":1805.3,"end":1807.57,"text":"Now, I want to hear from you.","words":[["Now, I want to hear from you.",1805.3]],"ipa":"/Now, I want to hear from you/"},{"start":1807.57,"end":1810.93,"text":"This is what makes our community so special.","words":[["This is what makes our community so special.",1807.57]],"ipa":"/This is what makes our community so special/"},{"start":1811.03,"end":1820.23,"text":"We are all human, and we all have feelings, no matter where we are in the world.","words":[["We are all human, and we all have feelings,",1811.03],["no matter where we are in the world.",1814.97]],"ipa":"/We are all human, and we all have feelings no matter where we are in the world/"},{"start":1820.33,"end":1825.97,"text":"But here's the thing - most people are afraid to share their real feelings.","words":[["But here's the thing",1820.33],["- most people are afraid to share their real feelings.",1822.13]],"ipa":"/But here's the thing most people are afraid to share their real feelings/"},{"start":1826.37,"end":1828.37,"text":"Not in our community!","words":[["Not in our community!",1826.37]],"ipa":"/Not in our community/"},{"start":1828.63,"end":1831.73,"text":"We're building something different here.","words":[["We're building something different here.",1828.63]],"ipa":"/We're building something different here/"},{"start":1831.93,"end":1837.37,"text":"Here's your mission - - and I challenge you to be brave and authentic.","words":[["Here's your mission -",1831.93],["- and I challenge you to be brave and authentic.",1833.53]],"ipa":"/Here's your mission and I challenge you to be brave and authentic/"},{"start":1837.73,"end":1851.83,"text":"In the comments below, please share: Your first name and where you're watching from - let's see how global our feelings family really is!","words":[["In the comments below, please share:",1837.73],["Your first name and where you're watching from",1842.47],["- let's see how global our feelings family really is!",1846.27]],"ipa":"/In the comments below, please share Your first name and where you're watching from let's see how global our feelings family really is/"},{"start":1851.97,"end":1858.03,"text":"Be completely honest How are you feeling RIGHT NOW as you watch this?","words":[["Be completely honest",1851.97],["How are you feeling RIGHT NOW as you watch this?",1854.17]],"ipa":"/Be completely honest How are you feeling RIGHT NOW as you watch this/"},{"start":1858.03,"end":1862.93,"text":"Don't just say \\"good\\" - dig deeper.","words":[["Don't just say \\"good\\" - dig deeper.",1858.03]],"ipa":"/Don't just say \\"good\\" - dig deeper/"},{"start":1862.93,"end":1870.23,"text":"Excited? Nervous? Hopeful? Tired but motivated?","words":[["Excited? Nervous? Hopeful? Tired but motivated?",1862.93]],"ipa":"/Excited? Nervous? Hopeful? Tired but motivated/"},{"start":1870.23,"end":1883.9,"text":"This isn't just homework - you're helping build a global community where people feel safe to express their authentic emotions in English.","words":[["This isn't just homework - you're helping build a global community",1870.23],["where people feel safe to express",1876.07],["their authentic emotions in English.",1879.3]],"ipa":"/This isn't just homework - you're helping build a global community where people feel safe to express their authentic emotions in English/"},{"start":1883.9,"end":1890.17,"text":"Think about it - when you share your feelings here, you're not just practicing English.","words":[["Think about it",1883.9],["- when you share your feelings here, you're not just practicing English.",1885.33]],"ipa":"/Think about it when you share your feelings here, you're not just practicing English/"},{"start":1890.17,"end":1901.27,"text":"You're helping someone in Brazil, India, or Germany feel less alone in their language learning journey.","words":[["You're helping someone in Brazil, India, or Germany",1890.17],["feel less alone in their language learning journey.",1895.5]],"ipa":"/You're helping someone in Brazil, India, or Germany feel less alone in their language learning journey/"},{"start":1901.27,"end":1908.2,"text":"When you learn to talk about feelings in English, You're not just learning vocabulary.","words":[["When you learn to talk about feelings in English,",1901.27],["You're not just learning vocabulary.",1905.17]],"ipa":"/When you learn to talk about feelings in English You're not just learning vocabulary/"},{"start":1908.2,"end":1913.23,"text":"You're learning to connect with people's hearts.","words":[["You're learning to connect with people's hearts.",1908.2]],"ipa":"/You're learning to connect with people's hearts/"},{"start":1913.8,"end":1916.1,"text":"You know what you've just unlocked?","words":[["You know what you've just unlocked?",1913.8]],"ipa":"/You know what you've just unlocked/"},{"start":1916.1,"end":1921.9,"text":"The secret to meaningful relationships in English.","words":[["The secret to meaningful relationships in English.",1916.1]],"ipa":"/The secret to meaningful relationships in English/"},{"start":1921.9,"end":1937.6,"text":"But more than that - you've gained the confidence to be vulnerable and authentic, which is the foundation of every deep human connection.","words":[["But more than that - you've gained the confidence",1921.9],["to be vulnerable and authentic,",1926.4],["which is the foundation of every deep human connection.",1930.13]],"ipa":"/But more than that - you've gained the confidence to be vulnerable and authentic which is the foundation of every deep human connection/"},{"start":1937.6,"end":1951.07,"text":"You now have the power to support others and build bridges between hearts, no matter what language they speak natively.","words":[["You now have the power to support others",1937.6],["and build bridges between hearts,",1941.63],["no matter what language they speak natively.",1945.77]],"ipa":"/You now have the power to support others and build bridges between hearts no matter what language they speak natively/"},{"start":1951.33,"end":1956.03,"text":"Before you go, I need you to make me a promise.","words":[["Before you go, I need you to make me a promise.",1951.33]],"ipa":"/Before you go, I need you to make me a promise/"},{"start":1956.03,"end":1959.03,"text":"Promise me you'll be brave.","words":[["Promise me you'll be brave.",1956.03]],"ipa":"/Promise me you'll be brave/"},{"start":1959.03,"end":1965.3,"text":"Promise me you'll share your real feelings - not just the \\"safe\\" ones.","words":[["Promise me you'll share your real feelings - not just the \\"safe\\" ones.",1959.03]],"ipa":"/Promise me you'll share your real feelings - not just the \\"safe\\" ones/"},{"start":1965.3,"end":1969.47,"text":"The world needs your authentic voice.","words":[["The world needs your authentic voice.",1965.3]],"ipa":"/The world needs your authentic voice/"},{"start":1969.53,"end":1974.77,"text":"Your feelings matter. Your story matters.","words":[["Your feelings matter. Your story matters.",1969.53]],"ipa":"/Your feelings matter. Your story matters/"},{"start":1974.77,"end":1988.23,"text":"Your journey matters. And every comment you share helps someone else feel less alone in their English learning adventure.","words":[["Your journey matters. And every comment you share",1974.77],["helps someone else feel less alone in their",1980.13],["English learning adventure.",1984.63]],"ipa":"/Your journey matters. And every comment you share helps someone else feel less alone in their English learning adventure/"},{"start":1988.23,"end":1990.63,"text":"Keep speaking with confidence.","words":[["Keep speaking with confidence.",1988.23]],"ipa":"/Keep speaking with confidence/"},{"start":1990.93,"end":1993.27,"text":"Keep connecting with your heart.","words":[["Keep connecting with your heart.",1990.93]],"ipa":"/Keep connecting with your heart/"},{"start":1993.63,"end":1997.13,"text":"Keep being beautifully, authentically you.","words":[["Keep being beautifully, authentically you.",1993.63]],"ipa":"/Keep being beautifully, authentically you/"},{"start":1997.47,"end":2010.83,"text":"Until tomorrow, take care of yourself and remember - - your feelings are valid, your voice matters, and your English is getting stronger every single day.","words":[["Until tomorrow, take care of yourself and remember -",1997.47],["- your feelings are valid, your voice matters,",2001.63],["and your English is getting stronger every single day.",2006.47]],"ipa":"/Until tomorrow, take care of yourself and remember your feelings are valid, your voice matters and your English is getting stronger every single day/"},{"start":2010.83,"end":2022.1,"text":"Bye everyone Take care and see you tomorrow.","words":[["Bye everyone",2010.83],["Take care and see you tomorrow.",2013.23]],"ipa":"/Bye everyone Take care and see you tomorrow/"}]`),u={id:e,youtubeId:t,title:o,channel:a,level:"A1",group:n,order:41,duration:2022,captions:s,segments:r};export{s as captions,a as channel,u as default,d as duration,n as group,e as id,i as level,l as order,r as segments,o as title,t as youtubeId};
